const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2,minimumFractionDigits:0}).format((n||0)/100);
let loginCsrf='';
function apiUrl(p){const u=new URL(p,location.origin);return 'api.php?route='+encodeURIComponent(u.pathname.replace(/^\/api\//,''))+(u.search?'&'+u.search.slice(1):'');}
let me,data,selectedDate,view='desk',filter='All',query='',cart=[],importPreview=null,importCsv='',importSource='daybook',lastSavedId=null;
/* V16: POS billing, Reservations and Guest feedback hidden from navigation (data and routes kept). */const nav=[['desk','⊞','Daily entry'],['daybook','▤','Daybook'],['paytm','⇄','Paytm & reconciliation'],['expenses','↗','Expenses'],['staff','♧','Staff & salaries'],['inventory','▥','Stock & suppliers'],['reports','▥','Reports'],['imports','↓','Import centre'],['settings','⚙','Settings']];
const accountOptions=(selected='Cash',unallocated=true)=>me.accounts.filter(x=>unallocated||x!=='Unallocated').map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
const options=(items,sel)=>items.map(x=>`<option value="${esc(x)}" ${x===sel?'selected':''}>${esc(x)}</option>`).join('');
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,opts)=>`<label class="field">${label}<select name="${name}">${opts}</select></label>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const card=(title,subtitle,body,action='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div><div class="card-body">${body}</div></section>`;
const table=(heads,rows,empty='No entries yet')=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`;
const amountField=(value='')=>`<label class="field wide">Amount (₹)<input class="amount-input" type="number" inputmode="decimal" name="amount" min="0.01" step="0.01" placeholder="0.00" value="${esc(value)}" required autofocus></label>`;
function toast(msg,error=false,undo=false){const t=$('#toast');t.innerHTML='<span>'+esc(msg)+'</span>'+(undo?'<button data-action="undo-entry">Undo entry ↶</button>':'');t.className=error?'error':'';t.style.display='flex';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',undo?15000:4500);}
async function api(p,b){const r=await fetch(apiUrl(p),b===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':me?.csrf||loginCsrf},body:JSON.stringify(b)});const text=await r.text();let j;try{j=JSON.parse(text);}catch{throw Error('The server returned an unexpected response. Check PHP and database setup.');}if(p==='/api/status'&&j.csrf)loginCsrf=j.csrf;if(!r.ok){if(r.status===401&&me){me=null;await boot();}throw Error(j.error||'Request failed');}return j;}
async function refresh(){data=await api(`/api/data?date=${selectedDate}&month=${selectedDate.slice(0,7)}`);if(["owner","manager","accountant"].includes(me.user.role))data.staffRecords=(await api("/api/staff-records")).records;render();}
async function boot(){const status=await api('/api/status');if(status.setup){location.href='install.php';return;}try{me=await api('/api/me');}catch{return login(false,status);}selectedDate=selectedDate||(me.demo?'2026-08-31':me.today);if(window.CRM&&await CRM.takeover(me))return;await refresh();}
function login(setup,status){app.innerHTML=`<div class="login-page"><div class="login-art"><div class="brand"><div class="brand-icon">d.</div><div><b>dhaba desk</b><small>RESTAURANT OPERATIONS</small></div></div><div><div class="eyebrow" style="color:#c4d5b6;margin-bottom:20px">A LITTLE ORDER. EVERY DAY.</div><h1>Your restaurant.<br>Your numbers.<br>One clear view.</h1><p>From the first cash entry to the last bill of the night. A calmer way to manage your restaurant.</p></div><small style="color:#91aa9c">Khadak Singh Da Dhaba · Alwar</small></div><div class="login-box"><form data-form="${setup?'setup':'login'}"><div class="eyebrow" style="margin-bottom:15px">WELCOME TO YOUR WORKSPACE</div><h1>${setup?'Make it yours.':'Welcome back.'}</h1><p>${setup?'Create your owner account to start recording your restaurant’s daily operations.':'Sign in to your restaurant operations desk.'}</p>${status.demo?'<div class="login-help">Sample workspace · 31 August 2026<br>Login details are filled in for the visual preview.</div>':''}${setup?field('Your name','name','text','','required')+field('Restaurant name','restaurant','text','Khadak Singh Da Dhaba','required'):''}${field('Email address','email','email','','required autocomplete="username"')}${field('Password','password','password','',`required ${setup?'minlength="12"':''} autocomplete="${setup?'new-password':'current-password'}"`)}<div class="form-error" id="login-error"></div><button class="primary full">${setup?'Create workspace':'Open my desk'} &nbsp; →</button><p style="font-size:10px;text-align:center;margin-top:18px">${status.demo?'Sample data is kept separate from live records.':'Your records are saved in your restaurant’s MySQL database.'}</p></form></div></div>`;}
function render(){const label=nav.find(n=>n[0]===view)?.[2]||'Daily entry';app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-icon">d.</div><div><b>dhaba desk</b><small>RESTAURANT OPERATIONS</small></div></div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav">${nav.slice(0,6).map(n=>navButton(n)).join('')}</nav><div class="nav-label">MANAGE & GROW</div><nav class="nav">${nav.slice(6).filter(n=>n[0]!=='settings'||me.user.role==='owner').map(n=>navButton(n)).join('')}</nav><div class="sidebar-bottom"><div class="branch"><span style="font-size:21px">⌖</span><div><b>Khadak Singh Da Dhaba</b><br><small>Alwar · Main outlet</small></div></div><div class="user"><div class="avatar">${esc(me.user.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.user.name)}</b><small>${esc(me.user.role)} workspace</small></div>${btn('↪','logout','','aria-label="Sign out"')}</div></div></aside><main class="main"><header class="topbar">${btn('☰','mobile','mobile-menu','aria-label="Open navigation"')}<div class="crumb">Workspace <span>/</span> <b>${label}</b></div><div class="top-actions"><span class="online-label"><span class="status-dot"></span> ${me.demo?'Sample workspace':'MySQL database'}</span><span style="color:#c2c9bb">|</span><input class="date-picker" type="date" id="business-date" aria-label="Business date" value="${selectedDate}"><div class="avatar" style="width:29px;height:29px;font-size:10px">${esc(me.user.name.slice(0,2).toUpperCase())}</div></div></header>${me.demo?`<div class="demo-bar"><span>◉ &nbsp; VISUAL PREVIEW · Your sample daybook · 31 August 2026</span><span>Separate demo database</span></div>`:''}<div class="content">${heading(label)}${screens[view]()}<footer class="page-foot"><span>dhaba desk &nbsp; / &nbsp; ${esc(me.restaurant)}</span><span>All amounts in INR · Business dates in India time</span></footer></div></main></div>`;}
function navButton(n){return `<button data-nav="${n[0]}" title="${n[2]}" aria-label="${n[2]}" class="${view===n[0]?'active':''}"><span class="icon">${n[1]}</span><span class="nav-text">${n[2]}</span></button>`;}
function heading(label){const titles={control:'Everything in one place.',desk:'Your daily entry desk.',daybook:'Your daily daybook.',pos:'Good food. Clear bills.',paytm:'Follow every payment.',expenses:'Keep the small costs visible.',staff:'Look after your team.',inventory:'Stock up. Stay ready.',reservations:'Make room for your guests.',reviews:'Listen. Respond. Improve.',reports:'Know how the day adds up.',imports:'Bring your numbers together.',settings:'Your restaurant, your rules.'};return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:9px">${view==='desk'?'YOUR DAILY OPERATIONS':label}</div><h1>${titles[view]}</h1><p>${view==='desk'?'Receive. Pay. Record. Keep every rupee in view.':new Date(selectedDate+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p></div><div class="heading-actions"><a class="outline" href="api.php?route=export&date=${selectedDate}"><button class="outline">↓ <span class="export-label">Export daybook</span></button></a>${btn('+ Add entry','entry','primary')}</div></div>`;}
function stats(){const s=data.summary;return `<div class="stats"><div class="stat featured"><div class="stat-top">Total money received <span class="stat-icon">↙</span></div><div class="stat-value">${fmt(s.received)}</div><div class="stat-foot"><b>↗</b> Sales & other receipts</div></div><div class="stat"><div class="stat-top">Total money paid <span class="stat-icon">↗</span></div><div class="stat-value">${fmt(s.paid)}</div><div class="stat-foot">Expenses & staff payments</div></div><div class="stat"><div class="stat-top">Net movement <span class="stat-icon">⇄</span></div><div class="stat-value">${fmt(s.net)}</div><div class="stat-foot"><b>●</b> Money received − money paid</div></div><div class="stat"><div class="stat-top">Paytm collections <span class="stat-icon" style="color:#4d99ad">₹</span></div><div class="stat-value">${fmt(data.paytm.filter(x=>x.kind==='payment'&&x.status==='success').reduce((a,x)=>a+x.amount,0))}</div><div class="stat-foot">${data.paytm.length?'Imported Paytm transactions':'No Paytm report imported yet'}</div></div></div>`;}
const quickTiles=[['cash','↙','Cash received','Sales & other receipts',''],['paytm-entry','₹','Online sale','Paytm / UPI sale entry','blue'],['expense','↗','Add expense','Supplies, bills & daily costs','orange'],['staff-payment','♧','Staff payment','Salary, advance & wages','orange'],['transfer','⇄','Move money','Cash to bank & transfers',''],['supplier-payment','▤','Supplier payment','Record a purchase payment','']];
function quickEntry(){return card('Make a quick entry','Pick a type → enter amount → save.',`<div class="entry-grid">${quickTiles.map(t=>`<button class="quick-tile ${t[4]}" data-action="${t[0]}"><span class="tile-icon">${t[1]}</span><span class="arrow">↗</span><b>${t[2]}</b><small>${t[3]}</small>${['cash','expense','paytm-entry'].includes(t[0])?'<kbd>'+({cash:'C',expense:'E','paytm-entry':'P'}[t[0]])+'</kbd>':''}</button>`).join('')}</div><div class="hint"><span>⌁</span> Keyboard shortcuts: E expense · C cash · P online sale. Amounts are entered in rupees.</div>`,badge(data.day.status==='closed'?'Day closed':'Day open',data.day.status==='closed'?'grey':''));}
function rowsFiltered(all=false){return data.ledger.filter(e=>!e.voided&&(filter==='All'||(filter==='Money in'?['sale','payment-in'].includes(e.type):!['sale','payment-in'].includes(e.type)))&&(!query||`${e.name} ${e.category} ${e.reference}`.toLowerCase().includes(query.toLowerCase()))).slice(0,all?5000:6);}
function ledgerTable(all=false){const rows=rowsFiltered(all);return `${table(['Entry','Payment','Money in','Money out',''],rows.map(e=>{const incoming=['sale','payment-in'].includes(e.type),transfer=['deposit','withdrawal','settlement'].includes(e.type);return `<tr><td><div class="entry-name"><span>${incoming?'↙':'↗'}</span><div>${esc(e.name)}<small>${esc(e.type)} ${e.reference?'· '+esc(e.reference):''}</small></div></div></td><td>${badge(e.account,e.account==='Unallocated'?'warn':'grey')}</td><td class="amount positive">${incoming?fmt(e.amount):'—'}</td><td class="amount negative">${!incoming&&!transfer?fmt(e.amount):'—'}</td><td>${e.account==='Unallocated'?btn('Split','allocate','small outline',`data-id="${e.id}"`):btn('···','entry-detail','small',`data-id="${e.id}" aria-label="View entry"`)}</td></tr>`;}))}<div class="table-footer"><span>${rows.length} of ${data.ledger.filter(x=>!x.voided).length} active entries</span><button class="text-link" data-nav="daybook">View full daybook →</button></div>`;}
function recent(all=false){return `<section class="card recent"><div class="card-head"><div><h2>${all?'Daybook entries':'Recent entries'}</h2><p>${all?'All receipts, expenses and transfers for this business date.':'The latest movements in your restaurant.'}</p></div>${badge(selectedDate,'grey')}</div><div class="table-toolbar"><div class="tabs">${['All','Money in','Money out'].map(x=>btn(x,'filter',x===filter?'selected':'',`data-filter="${x}"`)).join('')}</div><input class="search" id="entry-search" aria-label="Search entries" placeholder="Search entries…" value="${esc(query)}"></div><div id="ledger-table">${ledgerTable(all)}</div></section>`;}
function cashCard(){const s=data.summary,unallocated=!!s.unallocated;return `<section class="card cash-card"><div class="cash-title"><h2>Cash drawer</h2>${badge(data.day.status==='closed'?'Closed':'Open',data.day.status==='closed'?'grey':'')}</div><div class="balance-row"><span>Opening cash</span><b>${fmt(data.day.opening)}</b></div><div class="balance-row"><span>+ Cash received</span><b>${fmt(s.cashIn)}</b></div><div class="balance-row"><span>− Cash paid out</span><b>${fmt(s.cashOut)}</b></div><div class="balance-row total"><span>${unallocated?'Provisional cash':'Expected cash'}</span><b>${fmt(s.expectedCash)}</b></div>${btn(data.day.status==='closed'?'View closing':'Review & close day','close-day','primary full')}<p class="cash-note">${unallocated?'Mixed-payment sale needs allocation before closing.':data.day.counted!==null?'Counted: '+fmt(data.day.counted)+' · Difference: '+fmt(data.day.counted-s.expectedCash):'Count the drawer, compare, and close with confidence.'}</p><button class="text-link full" style="margin-top:12px" data-action="opening">Set opening cash</button></section>`;}
function integrations(){return card('Sources & quick links','Open your provider or import its report.',`<div class="connection"><div class="provider-icon pet">p.</div><div><b>Petpooja POS</b><small>${me.demo?'Sample daybook imported':'Sales report import available'}</small></div>${badge('Not linked','grey')}</div><div class="connection"><div class="provider-icon">pay</div><div><b>Paytm Business</b><small>Payments & bank settlements</small></div>${badge('Not linked','grey')}</div><div class="connection"><div class="provider-icon payroll-icon">A</div><div><b>Petpooja Payroll</b><small>Now Attendo · not synced</small></div><a class="external-link" href="https://payroll.petpooja.com/" target="_blank" rel="noopener noreferrer">Open ↗</a></div><button class="text-link" data-nav="imports" style="margin-top:17px">Import a report &nbsp; →</button>`);}
function allocationAlert(){return data.summary.unallocated?`<section class="alert-card"><h3>△ &nbsp; A little attention needed</h3><p>Your Petpooja sale includes cash and bank payments. Split <b>${fmt(data.summary.unallocated)}</b> by payment mode to get the correct cash balance.</p>${btn('Review mixed payment →','allocate-first')}</section>`:`<section class="alert-card"><h3>✓ &nbsp; Keep your day up to date</h3><p>Check Paytm collections against your bills and enter cash counted before closing.</p></section>`;}
function miniSummary(){const s=data.summary;return card('Where the money went','Daily outgoings by entry type.',[['expense','Expenses'],['payment-out','Other payments'],['salary','Salaries'],['advance','Staff advances']].map(([type,label])=>`<div class="metric-list"><span>${label}</span><b>${fmt(data.ledger.filter(e=>!e.voided&&e.type===type).reduce((a,e)=>a+e.amount,0))}</b></div>`).join(''));}
const screens={
desk:()=>`${stats()}<div class="workspace"><div>${attentionStrip()}${quickEntry()}${recent()}<div class="overview-bottom">${miniSummary()}${card('A clear day, at a glance','Receipts and outgoings for this day.',`<div class="bars">${[['Received',data.summary.received],['Paid out',data.summary.paid],['Net',data.summary.net]].map(([n,v],i)=>`<div class="bar-day"><b>${fmt(v)}</b><div class="bar ${i===2?'active':''}" style="height:${Math.max(3,Math.abs(v)/Math.max(data.summary.received,data.summary.paid,1)*82)}px"></div><span>${n}</span></div>`).join('')}</div>`)}</div></div><aside class="right-stack">${cashCard()}${allocationAlert()}</aside></div>`,
daybook:()=>`${stats()}<div class="workspace"><div>${data.summary.unallocated?'<div class="notification">Mixed payments are unallocated. The net movement is correct, but the cash drawer is provisional until you split the original payment.</div>':''}${recent(true)}</div><aside class="right-stack">${cashCard()}${allocationAlert()}</aside></div>`,
expenses:()=>`${card('Quick expense entry','Repeat the categories from your daybook.',`<div class="entry-grid">${['Vegetables','Overtime wages','Staff tips','Utilities','Bus tip / monthly','Other expense'].map(x=>`<button class="quick-tile orange" data-action="expense-category" data-category="${x}"><span class="tile-icon">↗</span><b>${x}</b><small>Record an expense</small></button>`).join('')}</div>`)}<section class="card recent"><div class="card-head"><h2>Expenses for this day</h2>${badge(fmt(data.ledger.filter(e=>!e.voided&&e.type==='expense').reduce((a,e)=>a+e.amount,0)))}</div>${table(['Expense','Category','Account','Amount'],data.ledger.filter(e=>!e.voided&&e.type==='expense').map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.category)}</td><td>${esc(e.account)}</td><td class="amount">${fmt(e.amount)}</td></tr>`))}</section>`,
paytm:()=>{const p=data.paytm,pay=p.filter(x=>x.kind==='payment'&&x.status==='success'),sum=pay.reduce((a,x)=>a+x.amount,0),sett=p.filter(x=>x.kind==='settlement'&&x.status==='success').reduce((a,x)=>a+x.amount,0);return `<div class="notification">Paytm is not linked. Import an official report using the template in Import centre. Collections and settlements stay separate; importing a payment does not create another sale.</div><div class="stats">${[['Successful collections',sum],['Settlements imported',sett],['Refunds imported',p.filter(x=>x.kind==='refund'&&x.status==='success').reduce((a,x)=>a+x.amount,0)],['Unmatched payments',pay.filter(x=>!x.matched_id).reduce((a,x)=>a+x.amount,0)]].map(([n,v])=>`<div class="stat"><div class="stat-top">${n}</div><div class="stat-value">${fmt(v)}</div></div>`).join('')}</div>${card('Paytm transaction register','Match successful collections with the corresponding Paytm sale.',table(['Reference','Kind','Status','Amount','Bill match'],p.map(x=>`<tr><td>${esc(x.external_id)}<small style="display:block">${esc(x.reference)}</small></td><td>${esc(x.kind)}</td><td>${badge(x.status,x.status==='success'?'':'warn')}</td><td class="amount">${fmt(x.amount)}</td><td>${x.matched_id?badge('Matched'):x.kind==='payment'&&x.status==='success'?btn('Match bill','match','small outline',`data-id="${x.id}"`):'—'}</td></tr>`)),btn('Import Paytm report','go-imports','outline'))}`;},
staff:()=>{if(!['owner','manager','accountant'].includes(me.user.role))return card('Restricted','Ask your owner for payroll access.','');return `${payrollConnection()}<div class="section-grid">${card('Your team','Monthly salaries and daily wages.',table(['Employee','Pay basis','Rate','Attendance'],data.employees.map(e=>`<tr><td><b>${esc(e.name)}</b><small style="display:block">${esc(e.job)}</small></td><td>${esc(e.pay_basis)}</td><td>${fmt(e.salary)}</td><td>${btn(data.attendance.find(a=>a.employee_id===e.id)?.status||'Mark','attendance','small',`data-id="${e.id}"`)}</td></tr>`)),btn('+ Employee','employee','outline'))}${card('Payroll · '+selectedDate.slice(0,7),'Review paid days, overtime, deductions, and advances.',`<div class="preview-note">Monthly pay uses the fixed rate. Daily pay uses approved paid days entered during calculation. Statutory deductions must be supplied by your accountant.</div><div style="margin-top:18px">${btn('Calculate payroll','payroll','primary')} ${btn('Record staff payment','staff-payment','outline')}</div>`)}</div><section class="card recent"><div class="card-head"><h2>Salary register</h2>${badge(selectedDate.slice(0,7),'grey')}</div>${table(['Employee','Earnings','Deductions','Advances','Net salary','Paid','Due','Status'],data.payroll.map(p=>`<tr><td>${esc(p.name)}</td><td>${fmt(p.gross)}</td><td>${fmt(p.deductions)}</td><td>${fmt(p.advance)}</td><td>${fmt(p.net)}</td><td>${fmt(p.paid)}</td><td class="amount">${fmt(p.net-p.paid)}</td><td>${p.approved?badge('Approved'):btn('Approve','approve-payroll','small outline',`data-id="${p.id}"`)}</td></tr>`))}</section>`;},
inventory:()=>`<div class="section-grid">${card('Stock on hand','Record receipts, usage, and wastage.',table(['Item','Stock','Reorder',''],data.inventory.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.quantity} ${esc(x.unit)}</td><td>${x.quantity<=x.reorder?badge('Low stock','warn'):badge('In stock')}</td><td>${btn('Adjust','stock','small',`data-id="${x.id}"`)}</td></tr>`)),btn('+ Item','inventory','outline'))}${card('Suppliers','Keep purchase contacts together.',table(['Name','Phone'],data.suppliers.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.phone)}</td></tr>`)),btn('+ Supplier','supplier','outline'))}</div><section class="card recent"><div class="card-head"><div><h2>Supplier bills</h2><p>Unpaid bills are tracked separately from cash payments.</p></div>${btn('+ Bill','bill','outline')}</div>${table(['Supplier','Invoice','Due date','Amount','Payment'],data.bills.map(b=>`<tr><td>${esc(b.supplier)}</td><td>${esc(b.reference)}</td><td>${esc(b.due_date)}</td><td class="amount">${fmt(b.amount)}</td><td>${b.ledger_id?badge('Paid'):btn('Pay bill','bill-pay','small outline',`data-id="${b.id}"`)}</td></tr>`))}</section>`,
reservations:()=>card('Today’s guest book','Bookings, seating, and no-shows.',table(['Time','Guest','Phone','Covers','Status',''],data.reservations.map(r=>`<tr><td>${esc(r.time)}</td><td>${esc(r.name)}</td><td>${esc(r.phone)}</td><td>${r.covers}</td><td>${badge(r.status,'grey')}</td><td>${btn('Update','reservation-status','small',`data-id="${r.id}"`)}</td></tr>`)),btn('+ Reservation','reservation','primary')),
reviews:()=>`<div class="notification">This is your first-party feedback register. Google Business Profile is not connected; no Google reviews are displayed or generated.</div>${card('Guest feedback','Track follow-up and record your response.',table(['Date','Rating','Feedback','Status',''],data.feedback.map(f=>`<tr><td>${esc(f.date)}</td><td style="color:#b58b3f">${'★'.repeat(f.rating)}</td><td>${esc(f.comment)}${f.response?'<small style="display:block;margin-top:5px">Response: '+esc(f.response)+'</small>':''}</td><td>${badge(f.status,'grey')}</td><td>${btn('Follow up','feedback-status','small',`data-id="${f.id}"`)}</td></tr>`)),btn('+ Feedback','feedback','primary'))}`,
reports:()=>`${stats()}<div class="section-grid">${miniSummary()}${card('Cash reconciliation','Opening balance + movements = expected closing cash.',`<div class="metric-list"><span>Opening cash</span><b>${fmt(data.day.opening)}</b></div><div class="metric-list"><span>Cash received</span><b>${fmt(data.summary.cashIn)}</b></div><div class="metric-list"><span>Cash paid out</span><b>${fmt(data.summary.cashOut)}</b></div><div class="metric-list"><span>Expected cash ${data.summary.unallocated?'(provisional)':''}</span><b>${fmt(data.summary.expectedCash)}</b></div><div class="metric-list"><span>Counted cash</span><b>${data.day.counted===null?'Not counted':fmt(data.day.counted)}</b></div>`)}</div><section class="card recent"><div class="card-head"><h2>Last seven days with entries</h2>${btn('Print report','print','outline')}</div>${table(['Business date','Sales','Expenses & salaries'],data.trend.map(x=>`<tr><td>${esc(x.date)}</td><td class="amount">${fmt(x.sales)}</td><td>${fmt(x.expenses)}</td></tr>`))}<div class="card-body"><p class="preview-note">Net movement is not profit. Supplier bills, stock valuation, accruals, and statutory adjustments require accounting review.</p></div></section>`,
imports:()=>`<div class="section-grid">${card('Import a report','Preview first. Save only after checking the entries.',`<form data-form="import-preview"><div class="form-grid">${select('Source','source',options(['daybook','petpooja','paytm'],importSource))}<label class="field">CSV file<input type="file" id="csv-file" accept=".csv,text/csv" required></label></div><div class="preview-note" style="margin-top:18px">Use the matching CSV template below. Native Petpooja / Paytm report columns may need mapping first. Amounts are in rupees. Reference numbers prevent duplicate imports.</div><div class="form-actions"><button class="primary">Preview import →</button></div></form>`)}${card('Download a template','Clear columns. Predictable imports.',`<div class="stack">${['daybook','petpooja','paytm'].map(x=>`<div class="balance-row no-margin"><span>${x==='daybook'?'Daily daybook':x==='petpooja'?'Petpooja sales':'Paytm transactions'}</span>${btn('↓ CSV template','template','outline small',`data-source="${x}"`)}</div>`).join('')}<div class="preview-note">For mixed payments, use Unallocated and split them after import. Paytm payment rows are reconciliation records; they do not add a second sale.</div></div>`)}</div>${importPreview?`<section class="card recent"><div class="card-head"><div><h2>Import preview</h2><p>${importPreview.added} new rows · ${importPreview.skipped} existing references skipped · first 50 rows shown</p></div>${btn('Confirm import','confirm-import','primary')}</div>${table(['Date','Reference','Name','Account','Amount'],importPreview.preview.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.reference)}</td><td>${esc(x.name)}</td><td>${esc(x.account)}</td><td>${esc(x.amount)}</td></tr>`))}</section>`:''}`,
settings:()=>`<div class="section-grid">${card('Restaurant settings','The name shown on your desk and receipts.',`<form data-form="settings">${field('Restaurant name','restaurant','text',me.restaurant,'required')}<div class="form-actions"><button class="primary">Save settings</button></div></form>`)}${card('Account & backup','Keep access and records under your control.',`${btn('Change my password','password','outline')} <a href="api.php?route=backup"><button class="outline">↓ Database SQL backup</button></a><p class="preview-note" style="margin-top:15px">SQL backup contains private financial and employee records. Store it securely. Restore into an empty database using phpMyAdmin.</p>`)}</div><section class="card recent"><div class="card-head"><h2>Team access</h2>${btn('+ User','user','outline')}</div>${table(['Name','Email','Role'],data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${badge(u.role,'grey')}</td></tr>`))}</section><section class="card recent"><div class="card-head"><h2>Activity history</h2><small>Latest 100 actions · UTC timestamps</small></div>${table(['When','Who','Action','Details'],data.audit.map(a=>`<tr><td>${esc(a.at)}</td><td>${esc(a.name||'Setup')}</td><td>${esc(a.action)}</td><td class="mono">${esc(a.detail)}</td></tr>`))}</section>`,
pos:()=>{const total=cart.reduce((a,x)=>a+x.quantity*x.price,0);return `<div class="notification">Use Petpooja as your billing source if you already bill there. Local POS is an alternative; importing the same bills from Petpooja would count them twice.</div><div class="pos-layout"><section class="card"><div class="card-head"><div><h2>Your menu</h2><p>Tap an item to add it to the bill.</p></div>${btn('+ Menu item','menu','outline small')}</div><div class="menu-grid">${data.menu.length?data.menu.map(m=>`<button class="menu-item" data-action="cart-add" data-id="${m.id}"><b>${esc(m.name)}</b><small>${esc(m.category)}</small><span>${fmt(m.price)} ＋</span></button>`).join(''):'<p class="empty">Add your first menu item to start billing.</p>'}</div></section><section class="card"><div class="card-head"><h2>Current bill</h2>${badge(cart.reduce((a,x)=>a+x.quantity,0)+' items','grey')}</div><div class="card-body"><form data-form="order"><div class="form-grid">${select('Order type','kind',options(['dine-in','takeaway','delivery']))}${field('Table','table_no','text','','placeholder="e.g. 04"')}</div>${cart.map(x=>`<div class="basket-row"><div>${esc(x.name)}<small style="display:block;margin-top:5px">${fmt(x.price)}</small></div><div class="qty">${btn('−','cart-less','small',`data-id="${x.id}"`)}${x.quantity}${btn('+','cart-add','small',`data-id="${x.id}"`)}</div></div>`).join('')}<div class="metric-list"><span>Subtotal</span><b>${fmt(total)}</b></div><div class="form-grid" style="margin-top:15px">${field('Discount (₹)','discount','number',0,'min="0" step="0.01"')}${field('Tax rate (%)','tax_rate','number',0,'min="0" max="30" step="0.01"')}</div><div class="metric-list"><span>Total</span><b id="order-total">${fmt(total)}</b></div><div style="margin-top:15px">${select('Payment account','account',accountOptions('Cash',false))}</div><button class="primary full" style="margin-top:18px" ${!cart.length?'disabled':''}>Save bill & payment →</button></form></div></section></div><section class="card recent"><div class="card-head"><h2>Saved bills</h2></div>${table(['Bill reference','Order type','Total',''],data.orders.map(o=>`<tr><td>${esc(o.reference)}</td><td>${esc(o.kind)} ${esc(o.table_no)}</td><td>${fmt(o.total)}</td><td>${btn('Receipt','receipt','outline small',`data-id="${o.id}"`)}</td></tr>`))}</section>`;}
};
function showModal(title,subtitle,body,form,submit='Save entry'){const content=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${btn('×','modal-close','','aria-label="Close dialog"')}</div><div class="modal-content">${form?`<form data-form="${form}">`:''}${body}${form?`<div class="form-error" id="modal-error"></div><div class="form-actions">${btn('Cancel','modal-close','outline','type="button"')}<button class="primary">${submit}</button></div></form>`:''}</div>`;$('#modal-body').innerHTML=content;modal.showModal();}
function entryModal(kind='expense',category=''){const presets={cash:['Cash received','sale','Cash'], 'paytm-entry':['Paytm received','sale','Paytm'],expense:['Add an expense','expense','Cash'],'staff-payment':['Staff payment','payment-out','Cash'],transfer:['Move money','deposit','Cash'],'supplier-payment':['Supplier payment','expense','Cash'],entry:['Add daybook entry','expense','Cash']};const [title,type,account]=presets[kind]||presets.entry;if(['expense','cash','paytm-entry','supplier-payment'].includes(kind))return simpleEntry(kind,category,title,type,account);const staff=kind==='staff-payment',transfer=kind==='transfer';showModal(title,'Saved to '+selectedDate+' · Amounts in rupees',`<div class="form-grid">${amountField()}${field(staff?'Employee / payment name':'Entry name','name','text',category,'required placeholder="What is this entry for?"')}${select('Entry type','type',options(staff?['payment-out','salary','advance']:transfer?['deposit','withdrawal','settlement']:me.types,type))}${select('Payment account','account',accountOptions(account))}${transfer?select('To account','to_account',accountOptions('Bank of India',false)):field('Category','category','text',category||'General')}${staff?select('Link employee (for salary / advance)','employee_id','<option value="">Not linked</option>'+data.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')):field('Reference (optional)','reference')}${staff?field('Payroll month','payroll_month','month',selectedDate.slice(0,7)):''}<label class="field wide">Note (optional)<textarea name="description" placeholder="Any detail you want to remember"></textarea></label></div>`,'entry');}
const forms={
employee:()=>showModal('Add employee','Set a monthly salary or daily wage.',`<div class="form-grid">${field('Full name','name','text','','required')}${field('Role / job','job')}${select('Pay basis','pay_basis',options(['monthly','daily']))}${field('Salary / daily rate (₹)','salary','number','','min="0" step="0.01" required')}</div>`,'employee','Add employee'),
inventory:()=>showModal('Add stock item','Use one consistent unit for each item.',`<div class="form-grid">${field('Item name','name','text','','required')}${field('Unit','unit','text','kg','required')}${field('Opening quantity','quantity','number',0,'min="0" step="0.001"')}${field('Reorder point','reorder','number',0,'min="0" step="0.001"')}${field('Unit cost (₹)','cost','number',0,'min="0" step="0.01"')}</div>`,'inventory','Add item'),
supplier:()=>showModal('Add supplier','Save purchase contact information.',`<div class="form-grid">${field('Supplier name','name','text','','required')}${field('Phone','phone','tel')}<label class="field wide">Notes<textarea name="notes"></textarea></label></div>`,'supplier','Add supplier'),
bill:()=>showModal('Record supplier bill','Bill entry does not reduce cash until payment is recorded.',`<div class="form-grid">${select('Supplier','supplier_id',data.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join(''))}${field('Invoice reference','reference','text','','required')}${field('Invoice date','date','date',selectedDate,'required')}${field('Due date','due_date','date',selectedDate,'required')}${amountField()}</div>`,'bill','Save bill'),
reservation:()=>showModal('New reservation','A quick note for the next service.',`<div class="form-grid">${field('Guest name','name','text','','required')}${field('Phone','phone','tel')}${field('Date','date','date',selectedDate,'required')}${field('Time','time','time','19:00','required')}${field('Guests','covers','number',2,'min="1" max="100" required')}${field('Notes','notes')}</div>`,'reservation','Save reservation'),
feedback:()=>showModal('Record guest feedback','First-party feedback only. This does not post to Google.',`<div class="form-grid">${field('Date','date','date',selectedDate)}${select('Rating','rating',options(['5','4','3','2','1']))}<label class="field wide">Feedback<textarea name="comment" required></textarea></label></div>`,'feedback','Save feedback'),
menu:()=>showModal('Add menu item','Set the selling price before tax.',`<div class="form-grid">${field('Item name','name','text','','required')}${field('Category','category','text','Food')}${field('Price (₹)','price','number','','min="0.01" step="0.01" required')}</div>`,'menu','Add item'),
user:()=>showModal('Add team access','Each staff member gets their own sign-in.',`<div class="form-grid">${field('Name','name','text','','required')}${field('Email','email','email','','required')}${select('Role','role',options(['cashier','chef','storekeeper','counter','purchase','housekeeping','employee','manager','accountant','owner']))}${field('Password','password','password','','required minlength="12" autocomplete="new-password"')}</div>`,'user','Create user'),
password:()=>showModal('Change password','At least 12 characters. Other sessions will be signed out.',`${field('Current password','old_password','password','','required autocomplete="current-password"')}${field('New password','password','password','','required minlength="12" autocomplete="new-password"')}`,'password','Update password'),
opening:()=>showModal('Opening cash','Use the actual cash carried into this business day.',`${field('Opening cash (₹)','opening','number',data.day.opening/100,'min="0" step="0.01" required')}${field('Note','note','text',data.day.note)}`,'day','Save opening'),
payroll:()=>showModal('Calculate payroll','Review days and deductions before approval.',`<div class="form-grid">${select('Employee','employee_id',data.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join(''))}${field('Month','month','month',selectedDate.slice(0,7),'required')}${field('Paid days (daily wage only)','paid_days','number',0,'min="0" max="31" step="0.5"')}${field('Overtime amount (₹)','overtime','number',0,'min="0" step="0.01"')}${field('Bonus (₹)','bonus','number',0,'min="0" step="0.01"')}${field('Other deductions (₹)','deductions','number',0,'min="0" step="0.01"')}</div><div class="preview-note" style="margin-top:15px">Recorded advances for this payroll month are deducted automatically. Check attendance before entering paid days.</div>`,'payroll','Calculate salary')
};
async function action(a,id,target){if(typeof staffAction==='function'&&staffAction(a,id,target))return;if(a==='payroll-info')return showModal('Petpooja Payroll connection','Attendo · external payroll workspace',`<div class="connection-info"><p>The login link is ready. Your account has not been connected or accessed.</p><ol><li>Open Petpooja Payroll and sign in yourself.</li><li>Export the attendance and salary reports you want to bring in.</li><li>We will map employee IDs, salary months, advances and payment status.</li><li>Enable automatic sync only after Petpooja confirms approved API access.</li></ol><p class="preview-note">Keep Petpooja Payroll as the source for salary calculations. This daybook should record actual payments separately so a payroll liability is not mistaken for cash paid.</p><a class="external-link primary-link" href="https://payroll.petpooja.com/" target="_blank" rel="noopener noreferrer">Open Petpooja Payroll ↗</a></div>`);if(a==='undo-entry'){if(!lastSavedId)throw Error('No quick entry to undo');await api('/api/void',{id:lastSavedId,reason:'Undo immediately after quick entry'});lastSavedId=null;toast('Entry undone. Correction is retained in the activity history.');return refresh();}if(a==='pick-category'){const f=target.closest('form');f.elements.name.value=target.dataset.category;f.elements.category.value=target.dataset.category;f.querySelectorAll('[data-action="pick-category"]').forEach(x=>x.classList.toggle('selected',x===target));return;}if(a==='pick-account'){const f=target.closest('form');f.elements.account.value=target.dataset.account;f.querySelectorAll('[data-action="pick-account"]').forEach(x=>x.classList.toggle('selected',x===target));return;}if(a==='keypad'){const f=target.closest('form'),input=f.elements.amount,key=target.dataset.key;let v=input.value||'';if(key==='clear')v='';else if(key==='back')v=v.slice(0,-1);else if(key==='.'&&!v.includes('.'))v=(v||'0')+'.';else if(key!=='.'&&(!v.includes('.')||v.split('.')[1].length<2)&&v.length<12)v=v==='0'?key:v+key;input.value=v;return;}if(a==='amount-preset'){target.closest('form').elements.amount.value=target.dataset.amount;return;}if(forms[a])return forms[a]();if(quickTiles.some(t=>t[0]===a)||a==='entry')return entryModal(a);if(a==='expense-category')return entryModal('expense',target.dataset.category);if(a==='modal-close')return modal.close();if(a==='mobile')return $('.sidebar').classList.toggle('open');if(a==='logout'){await api('/api/logout',{});me=null;return boot();}if(a==='filter'){filter=target.dataset.filter;return render();}if(a==='go-imports'){view='imports';return render();}if(a==='print')return window.print();
if(a==='allocate-first')id=data.ledger.find(x=>!x.voided&&x.account==='Unallocated')?.id,a='allocate';
if(a==='allocate'){const e=data.ledger.find(x=>x.id===Number(id));return showModal('Split mixed payment',`${e.name} · Total ${fmt(e.amount)}`,`<input type="hidden" name="id" value="${id}"><div class="preview-note">Use the original cash and bank totals from your POS report. Both amounts must add up to ${fmt(e.amount)}.</div><div class="form-grid" style="margin-top:18px">${select('Account 1','account1',accountOptions('Cash',false))}${field('Amount 1 (₹)','amount1','number','','min="0.01" step="0.01" required')}${select('Account 2','account2',accountOptions('Bank of India',false))}${field('Amount 2 (₹)','amount2','number','','min="0.01" step="0.01" required')}</div>`,'allocate','Save split');}
if(a==='entry-detail'){const e=data.ledger.find(x=>x.id===Number(id));return showModal(esc(e.name),`Entry #${id} · ${esc(e.source)}`,`<div class="metric-list"><span>Amount</span><b>${fmt(e.amount)}</b></div><div class="metric-list"><span>Account</span><b>${esc(e.account)} ${e.to_account?'→ '+esc(e.to_account):''}</b></div><p class="preview-note" style="margin-top:16px">${esc(e.description||'No additional notes')}</p><form data-form="void" style="margin-top:18px"><input type="hidden" name="id" value="${id}">${field('Correction reason','reason','text','','required')}<div class="form-actions"><button class="danger">Void this entry</button></div></form>`);}
if(a==='close-day'){if(data.day.status==='closed')return showModal('Day closed',selectedDate,`<div class="metric-list"><span>Counted</span><b>${fmt(data.day.counted)}</b></div><p class="preview-note" style="margin-top:15px">${esc(data.day.note)}</p>${me.user.role==='owner'?`<form data-form="reopen" style="margin-top:15px">${field('Reason for reopening','reason','text','','required')}<div class="form-actions"><button class="outline">Reopen day</button></div></form>`:''}`);return showModal('Review & close day',selectedDate,`<div class="metric-list"><span>Expected cash ${data.summary.unallocated?'(provisional)':''}</span><b>${fmt(data.summary.expectedCash)}</b></div>${data.summary.unallocated?'<div class="notification" style="margin-top:16px">Allocate mixed payments before closing this day.</div>':''}<div style="margin-top:18px">${field('Cash actually counted (₹)','counted','number','','min="0" step="0.01" required')}${field('Closing note / explanation of difference','note','text',data.day.note)}</div>`,'close','Close business day');}
if(a==='attendance'){const e=data.employees.find(x=>x.id===Number(id));return showModal('Attendance · '+esc(e.name),selectedDate,`<input name="employee_id" type="hidden" value="${id}">${select('Status','status',options(['present','half-day','absent','paid-leave'],data.attendance.find(x=>x.employee_id===e.id)?.status))}`,'attendance','Save attendance');}
if(a==='approve-payroll'){await api('/api/payroll-approve',{id});toast('Payroll approved');return refresh();}
if(a==='stock'){const x=data.inventory.find(x=>x.id===Number(id));return showModal('Stock movement · '+esc(x.name),`Current stock: ${x.quantity} ${esc(x.unit)}`,`<input name="id" type="hidden" value="${id}">${field('Quantity (+ received / − used)','quantity','number','','step="0.001" required')}${field('Reason','reason','text','','required placeholder="Purchase, usage, wastage, or count correction"')}`,'stock','Save movement');}
if(a==='bill-pay')return showModal('Pay supplier bill','This creates an expense entry in the daybook.',`<input name="id" type="hidden" value="${id}">${select('Payment account','account',accountOptions('Cash',false))}`,'bill-pay','Record payment');
if(a==='reservation-status')return showModal('Update reservation','Track service progress.',`<input name="id" type="hidden" value="${id}">${select('Status','status',options(['booked','seated','completed','cancelled','no-show']))}`,'reservation-status','Save status');
if(a==='feedback-status'){const f=data.feedback.find(x=>x.id===Number(id));return showModal('Guest follow-up','Record an internal response; this does not publish online.',`<input name="id" type="hidden" value="${id}">${select('Status','status',options(['new','in progress','resolved'],f.status))}<label class="field" style="margin-top:15px">Response<textarea name="response">${esc(f.response)}</textarea></label>`,'feedback-status','Save follow-up');}
if(a==='match'){const p=data.paytm.find(x=>x.id===Number(id)),rows=data.ledger.filter(e=>!e.voided&&e.type==='sale'&&e.account==='Paytm'&&e.amount===p.amount&&!data.paytm.some(x=>x.matched_id===e.id));return showModal('Match Paytm payment',`${p.external_id} · ${fmt(p.amount)}`,`<input name="paytm_id" type="hidden" value="${id}">${select('Matching bill','ledger_id',rows.map(e=>`<option value="${e.id}">${esc(e.reference||e.name)} · ${fmt(e.amount)}</option>`).join(''))}${!rows.length?'<p class="form-error">No unmatched sale has the same amount. Check the Petpooja report first.</p>':''}`,'match','Match payment');}
if(a==='template')return downloadTemplate(target.dataset.source);
if(a==='confirm-import'){const r=await api('/api/import',{source:importSource,csv:importCsv});importPreview=null;toast(`${r.added} entries imported; ${r.skipped} duplicates skipped`);return refresh();}
if(a==='cart-add'){const m=data.menu.find(x=>x.id===Number(id));const c=cart.find(x=>x.id===m.id);if(c)c.quantity++;else cart.push({...m,quantity:1});return render();}
if(a==='cart-less'){const c=cart.find(x=>x.id===Number(id));if(c.quantity>1)c.quantity--;else cart=cart.filter(x=>x.id!==c.id);return render();}
if(a==='receipt'){const o=data.orders.find(x=>x.id===Number(id));return showModal('Bill receipt',o.reference,`<div class="receipt"><h2>${esc(me.restaurant)}</h2><p>${esc(o.date)} · ${esc(o.kind)} ${esc(o.table_no)}</p><p>${esc(o.reference)}</p>${JSON.parse(o.items).map(x=>`<div class="metric-list"><span>${esc(x.name)} × ${x.quantity}</span><b>${fmt(x.price*x.quantity)}</b></div>`).join('')}<div class="metric-list"><span>Discount</span><b>${fmt(o.discount)}</b></div><div class="metric-list"><span>Tax</span><b>${fmt(o.tax)}</b></div><div class="metric-list"><span>Total paid</span><b>${fmt(o.total)}</b></div><p style="text-align:center;margin-top:18px">Thank you for dining with us.</p></div><div class="form-actions">${btn('Print receipt','print','primary')}</div>`);}
}
function downloadTemplate(source){const content=source==='paytm'?'date,reference,bill_reference,amount,status,kind,fee\r\n2026-08-31,EXAMPLE-PAYTM-001,EXAMPLE-BILL-001,500,success,payment,0\r\n':source==='petpooja'?'date,reference,name,account,amount,description\r\n2026-08-31,EXAMPLE-BILL-001,Petpooja sale,Paytm,500,Example only - replace before import\r\n':'date,reference,name,type,account,to_account,amount,category,description\r\n2026-08-31,EXAMPLE-EXP-001,Vegetables,expense,Cash,,560,Vegetables,Example only - replace before import\r\n';const url=URL.createObjectURL(new Blob([content],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=source+'-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
document.addEventListener('click',async ev=>{const n=ev.target.closest('[data-nav]');if(n){view=n.dataset.nav;filter='All';query='';render();return;}const t=ev.target.closest('[data-action]');if(t){ev.preventDefault();try{await action(t.dataset.action,t.dataset.id,t);}catch(e){toast(e.message,true);}}});
document.addEventListener('change',async ev=>{if(ev.target.id==='business-date'){selectedDate=ev.target.value;try{await refresh();}catch(e){toast(e.message,true);}}});
document.addEventListener('input',ev=>{if(ev.target.id==='entry-search'){query=ev.target.value;$('#ledger-table').innerHTML=ledgerTable(view==='daybook');}if(view==='pos'&&['discount','tax_rate'].includes(ev.target.name)){const form=ev.target.form,total=cart.reduce((a,x)=>a+x.quantity*x.price,0),disc=Math.round(Number(form.discount.value||0)*100),tax=Math.round((total-disc)*Number(form.tax_rate.value||0)/100);$('#order-total').textContent=fmt(total-disc+tax);}});
document.addEventListener('submit',async ev=>{const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const kind=form.dataset.form,b=Object.fromEntries(new FormData(form)),submit=form.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(kind==='setup'){await api('/api/setup',b);toast('Owner account created. Sign in to continue.');return boot();}if(kind==='login'){await api('/api/login',b);return boot();}if(kind==='import-preview'){const file=$('#csv-file').files[0];if(!file)throw Error('Choose a CSV file');importSource=b.source;importCsv=await file.text();importPreview=await api('/api/import',{source:importSource,csv:importCsv,preview:true});render();return;}if(kind==='allocate'){b.splits=[{account:b.account1,amount:b.amount1},{account:b.account2,amount:b.amount2}];if(b.account1===b.account2)throw Error('Choose two different accounts');}if(['entry','day','close','reopen','attendance','stock','bill-pay','order'].includes(kind))b.date=selectedDate;if(kind==='order'){b.items=cart.map(x=>({id:x.id,quantity:x.quantity}));const subtotal=cart.reduce((a,x)=>a+x.quantity*x.price,0),disc=Math.round(Number(b.discount)*100),tax=Math.round((subtotal-disc)*Number(b.tax_rate)/100);b.payments=[{account:b.account,amount:(subtotal-disc+tax)/100}];}if(kind==='staff-record')b.payload={...b};const saved=await api('/api/'+kind,b);if(kind==='entry')lastSavedId=saved.id;if(kind==='order')cart=[];if(kind==='settings')me=await api('/api/me');modal.close();toast(kind==='close'?'Day closed successfully':kind==='entry'?`${fmt(Math.round(Number(b.amount)*100))} · ${b.name} · saved`:'Saved to your workspace',false,kind==='entry');await refresh();}catch(e){const box=$('#modal-error')||$('#login-error');if(box)box.textContent=e.message;else toast(e.message,true);}finally{if(submit)submit.disabled=false;}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});

function attentionStrip(){const n=data.ledger.filter(x=>!x.voided&&x.account==='Unallocated').length;return n?'<div class="attention-strip"><div><span class="attention-icon">!</span><div><b>Confirm the payment split</b><small>'+fmt(data.summary.unallocated)+' is waiting for cash / bank allocation. Cash balance is provisional.</small></div></div>'+btn('Review split →','allocate-first','small')+'</div>':'';}
function payrollConnection(){return '<section class="payroll-banner"><div class="payroll-banner-title"><div class="provider-icon payroll-icon">A</div><div><b>Petpooja Payroll <span class="muted">/ Attendo</span></b><p>Attendance & salary workspace · login link ready · data not synced</p></div></div><div class="payroll-banner-actions">'+btn('Connection details','payroll-info','outline small')+'<a class="external-link primary-link" href="https://payroll.petpooja.com/" target="_blank" rel="noopener noreferrer">Open Payroll ↗</a></div></section>';}
function simpleEntry(kind,category,title,type,account){const cats=kind==='expense'?['Vegetables','Milk & dairy','Groceries','Overtime wages','Staff tips','Utilities','Travel','Other expense']:kind==='supplier-payment'?['Vegetable supplier','Dairy supplier','Groceries supplier','Other supplier']:['Counter sales','Takeaway sales','Other receipt'];const selected=category||cats[0];showModal(title,'Quick entry · '+selectedDate,`<div class="quick-form-body"><div class="quick-entry-fields"><input name="type" type="hidden" value="${type}"><input name="category" type="hidden" value="${selected}"><input name="account" type="hidden" value="${account}">${amountField().replace('type="number"','type="text"')}<div class="amount-presets">${[100,500,1000,2000].map(n=>btn('₹'+n,'amount-preset','small','type="button" data-amount="'+n+'"')).join('')}</div><div class="field-label">${type==='sale'?'Receipt type':'Common categories'}</div><div class="category-pills">${cats.map(c=>btn(esc(c),'pick-category',c===selected?'selected':'','type="button" data-category="'+esc(c)+'"')).join('')}</div>${field('Entry name','name','text',selected,'required')}<div class="field-label" style="margin-top:16px">Payment account</div><div class="account-pills">${['Cash','Paytm','Bank of India'].map(a=>btn(a,'pick-account',a===account?'selected':'','type="button" data-account="'+a+'"')).join('')}</div><details class="extra-details"><summary>+ Note or reference</summary>${field('Reference (optional)','reference')}${field('Note (optional)','description')}</details>${kind==='paytm-entry'?'<p class="entry-caution">Record a sale here only if it will not also be imported from Petpooja. Use Paytm reports to match payments.</p>':''}</div><div class="keypad-panel"><div class="eyebrow">QUICK KEYPAD</div><div class="keypad">${['7','8','9','4','5','6','1','2','3','.','0','back'].map(k=>btn(k==='back'?'⌫':k,'keypad','','type="button" aria-label="'+(k==='back'?'Delete last digit':k)+'" data-key="'+k+'"')).join('')}</div>${btn('Clear amount','keypad','keypad-clear','type="button" data-key="clear"')}<div class="keypad-note">Saved to the daybook.<br>Undo is available after saving.</div></div></div>`,'entry','Save '+(kind==='expense'?'expense':'entry')+' →');modal.classList.add('quick-dialog');}
document.addEventListener('keydown',ev=>{if(ev.ctrlKey||ev.metaKey||ev.altKey||modal.open||!me||!data||/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)||ev.target.isContentEditable)return;const kind={e:'expense',c:'cash',p:'paytm-entry'}[ev.key.toLowerCase()];if(kind&&view==='desk'){ev.preventDefault();entryModal(kind);}});
modal.addEventListener('close',()=>modal.classList.remove('quick-dialog'));

boot().catch(e=>{app.innerHTML=`<div class="loading">${esc(e.message)} · Restart the local server and refresh.</div>`;});




